s":1,"maxItems":128,"items":{"\$ref":"#/\$defs/Answer"}}}},"Answer":{"title":"Answer","description":"The answer to one question. Exactly one member besides `question` is present, matching the question\'s type, or `abstain` for an optional question left unanswered.","type":"object","additionalProperties":false,"required":["question"],"minProperties":2,"maxProperties":2,"properties":{"question":{"\$ref":"#/\$defs/Key"},"choice":{"type":"array","items":{"\$ref":"#/\$defs/Key"},"uniqueItems":true},"ranking":{"type":"array","items":{"\$ref":"#/\$defs/Key"},"uniqueItems":true},"scores":{"type":"object","propertyNames":{"\$ref":"#/\$defs/Key"},"additionalProperties":{"type":"integer"}},"text":{"type":"string","maxLength":4096},"abstain":{"const":true}}},"Key":{"title":"Key","description":"A question or option key, unique within its manifest or question.","type":"string","pattern":"^[A-Za-z0-9._-]{1,64}\$"},"ElectionId":{"title":"ElectionId","description":"An election\'s identifier, unique within its community. A closed alphabet: it appears in the ticket class label `voter/<electionId>` and is framed into every hash a cast is bound to.","type":"string","pattern":"^[A-Za-z0-9._-]{1,128}\$"},"DigestMultibase":{"title":"DigestMultibase","description":"A cryptographic digest as a multibase-encoded multihash — the encoding the W3C Verifiable Credentials Data Model 2.0 defines for `digestMultibase`, and the one `did:webvh` uses for its SCID and entry hashes.\\n\\nMultihash carries the hash algorithm in-band, so the value is self-describing and the wire format survives an algorithm change without a schema revision; multibase does the same for the base encoding, so a verifier never infers base58 from base64url by context. A bare hex string or a `sha-256:`-style prefix hard-codes one algorithm into the wire contract and is non-conforming here.\\n\\nThis definition constrains the *encoding only*. What the digest is computed over is stated by each referencing field, because it differs legitimately: a digest over a JSON document is taken over its RFC 8785 (JCS) canonicalization, while a digest over an opaque artifact is taken over its bytes. A field whose input is a JSON document and which does not name a canonicalization is not reproducible.\\n\\nRestricted to the two multibase headers W3C Controlled Identifiers 1.0 §2.4 normatively requires — `z` (base58btc) and `u` (base64url-no-pad). CID permits others but states that \\"interoperability is not guaranteed between implementations using such values\\", and a registry whose purpose is interoperability should not mint digests a conforming verifier may be unable to read. The alphabets are enforced rather than assumed: base58btc excludes 0, O, I and l, and an earlier permissive pattern let three published examples carry digests that were not valid base58 at all. base58btc is RECOMMENDED, for consistency with `did:key` and `did:webvh`.","type":"string","minLength":16,"pattern":"^(z[1-9A-HJ-NP-Za-km-z]+|u[A-Za-z0-9_-]+)\$","examples":["zQmbWqxBEKC3P8tqsKc98xmWNzrzDtRLMiMPL8wBuTGsMnR"]},"Manifest":{"title":"Manifest","description":"What an election asks and how it is decided (VTI-VOT-010). Its digest (`manifestDigest`) is the SHA-256 multihash of its RFC 8785 (JCS) canonicalization, and every cast is bound to it (VTI-VOT-011).","type":"object","additionalProperties":false,"required":["electionId","community","questions","secrecy","roll","registrationOpensAt","votingOpensAt","votingClosesAt","revote","board","ballotBox","binding","allowEarlyClose","resultsBeforeClose","textReleaseThreshold"],"properties":{"electionId":{"\$ref":"#/\$defs/ElectionId"},"community":{"type":"string","minLength":1,"maxLength":2048,"description":"The community\'s DID."},"title":{"type":"string","maxLength":512},"description":{"type":"string","maxLength":8192},"questions":{"type":"array","minItems":1,"maxItems":128,"items":{"\$ref":"#/\$defs/Question"}},"secrecy":{"\$ref":"#/\$defs/SecrecyLevel"},"roll":{"\$ref":"#/\$defs/RollRule"},"registrationOpensAt":{"type":"string","format":"date-time"},"votingOpensAt":{"type":"string","format":"date-time"},"votingClosesAt":{"type":"string","format":"date-time"},"revote":{"\$ref":"#/\$defs/Revote"},"board":{"type":"object","additionalProperties":false,"required":["visibility","auditors"],"properties":{"visibility":{"\$ref":"#/\$defs/BoardVisibility"},"auditors":{"type":"array","items":{"type":"string","minLength":1,"maxLength":2048},"uniqueItems":true}}},"ballotBox":{"type":"string","minLength":1,"maxLength":2048,"description":"The DID of the voting service that holds the board."},"trustees":{"\$ref":"#/\$defs/Trustees"},"binding":{"type":"boolean","description":"Whether the community treats the result as deciding something; creating a binding election takes another administrator\'s consent (VTI-VOT-081)."},"allowEarlyClose":{"type":"boolean"},"resultsBeforeClose":{"type":"boolean","description":"Open elections only: whether running totals may be read while voting is open (VTI-VOT-061)."},"textReleaseThreshold":{"type":"integer","minimum":10,"description":"Counted ballots required before any text answer is disclosed (VTI-VOT-065)."}}},"Trustees":{"title":"Trustees","description":"The trustees of a sealed or tallied-encrypted election and the number of them decryption needs (VTI-VOT-062). Neither the community nor the ballot box may be one.","type":"object","additionalProperties":false,"required":["dids","threshold"],"properties":{"dids":{"type":"array","minItems":2,"items":{"type":"string","minLength":1,"maxLength":2048},"uniqueItems":true},"threshold":{"type":"integer","minimum":2}}},"BoardVisibility":{"title":"BoardVisibility","description":"`public`: anyone reads the board. `private`: the community, the auditors the manifest names and, for one cast\'s inclusion, the holder of its receipt (VTI-VOT-052).","type":"string","enum":["public","private"]},"Revote":{"title":"Revote","description":"What a later, different ballot under one ticket does: `replace` the earlier one, or be refused (`refuse`) (VTI-VOT-041).","type":"string","enum":["replace","refuse"]},"RollRule":{"title":"RollRule","description":"Who may be issued a ticket (VTI-VOT-021): the community\'s active members, its active members and the parties `listed` names, or only the parties `listed` names.","type":"object","additionalProperties":false,"required":["rule"],"properties":{"rule":{"type":"string","enum":["members","membersAndListed","listed"]},"listed":{"type":"array","items":{"type":"string","minLength":1,"maxLength":2048,"description":"A DID enfranchised by name."},"uniqueItems":true}}},"SecrecyLevel":{"title":"SecrecyLevel","description":"`open`: ballots are recorded on the board as cast. `sealed`: ballots are encrypted to a jointly generated election key and decrypted after voting closes. `talliedEncrypted`: ballots are encrypted and only the totals are ever decrypted (VTI-VOT-060). The encrypted levels are cast with `voting/ballot/cast-encrypted/0.1`, under an election key the trustees generate with `voting/trustees/*` (CONVENTIONS §9).","type":"string","enum":["open","sealed","talliedEncrypted"]},"Question":{"title":"Question","description":"One question. Tagged union over `type`.","oneOf":[{"title":"ChoiceQuestion","description":"Select between `minSelections` and `maxSelections` of `options`. A yes/no/abstain motion is a choice of exactly one of three.","type":"object","additionalProperties":false,"required":["key","type","options","minSelections","maxSelections","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"choice"},"text":{"type":"string","maxLength":2048},"options":{"type":"array","minItems":2,"maxItems":256,"items":{"\$ref":"#/\$defs/QuestionOption"}},"minSelections":{"type":"integer","minimum":0},"maxSelections":{"type":"integer","minimum":1},"optional":{"type":"boolean"}}},{"title":"RankingQuestion","description":"Order `options`; a ballot ranks every option or, when `partial` is true, a prefix of them.","type":"object","additionalProperties":false,"required":["key","type","options","partial","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"ranking"},"text":{"type":"string","maxLength":2048},"options":{"type":"array","minItems":2,"maxItems":64,"items":{"\$ref":"#/\$defs/QuestionOption"}},"partial":{"type":"boolean"},"optional":{"type":"boolean"}}},{"title":"ScoreQuestion","description":"Give each option an integer score within [min, max].","type":"object","additionalProperties":false,"required":["key","type","options","min","max","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"score"},"text":{"type":"string","maxLength":2048},"options":{"type":"array","minItems":1,"maxItems":256,"items":{"\$ref":"#/\$defs/QuestionOption"}},"min":{"type":"integer"},"max":{"type":"integer"},"optional":{"type":"boolean"}}},{"title":"TextQuestion","description":"Free text of at most `maxLength` characters.","type":"object","additionalProperties":false,"required":["key","type","maxLength","optional"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"type":{"const":"text"},"text":{"type":"string","maxLength":2048},"maxLength":{"type":"integer","minimum":1,"maximum":4096},"optional":{"type":"boolean"}}}]},"QuestionOption":{"title":"QuestionOption","type":"object","additionalProperties":false,"required":["key"],"properties":{"key":{"\$ref":"#/\$defs/Key"},"label":{"type":"string","maxLength":512,"description":"Display text. Absent from a manifest registered with a ballot box that holds no question text (VTI-VOT-014)."}}},"VotingParameters":{"title":"VotingParameters","description":"The community\'s published voting parameters: the PCS suite and the voting verification key tickets are issued under (VTI-VOT-020). Distinct from its hidden-vetting helper key.","type":"object","additionalProperties":false,"required":["suite","votingKey"],"properties":{"suite":{"type":"string","const":"ps-ddh-bls12381"},"votingKey":{"\$ref":"#/\$defs/Multibase"}}},"Multibase":{"title":"Multibase","description":"A binary value, multibase base58btc over the suite\'s canonical (compressed) encoding.","type":"string","maxLength":16384,"pattern":"^z[1-9A-HJ-NP-Za-km-z]+\$"}}}';

